<template><div class="joint-row" :data-joint-id="joint.id"><span>{{joint.name}}</span><el-slider :model-value="value" :min="joint.limit.lower??-3.14" :max="joint.limit.upper??3.14" :step="0.01" @input="preview" @change="commit"/><b>{{value.toFixed(3)}}</b></div></template>
<script setup lang="ts">import type {JointNode} from '@/types/scene';const props=defineProps<{joint:JointNode;value:number}>();const emit=defineEmits<{preview:[id:string,value:number];commit:[id:string,value:number]}>();function number(value:number|number[]){return Number(value)}function preview(value:number|number[]){emit('preview',props.joint.id,number(value))}function commit(value:number|number[]){emit('commit',props.joint.id,number(value))}</script>
